async function loadImages(){function e(e){return new Promise(t=>{e.onload=()=>{e.classList.remove("differed-img"),t(e)},e.src=e.dataset.src.replace(".jpg","-preview.webp"),e.removeAttribute("data-src")})}let t=document.querySelectorAll(".differed-img");t.forEach(async function(t){await e(t)})}document.addEventListener("DOMContentLoaded",function(){loadImages()});